import Foundation
import AVFoundation
import Combine
import UserNotifications

// MARK: - Puzzle data (loaded from bundled JSON, generated by tools/gen_puzzles.py)

struct PuzzleCell: Codable {
    /// "x" = black, "c" = clue, "l" = letter
    var k: String
    var s: String?    // solution letter (letter cells)
    var ca: String?   // across clue (clue cells)
    var cd: String?   // down clue (clue cells)
    var b: Bool?      // blue bonus square
}

struct PuzzleWord: Codable {
    var a: String     // answer
    var r: Int
    var c: Int
    var d: String     // "across" | "down"
}

struct Puzzle: Codable, Identifiable {
    var id: String
    var title: String
    var cols: Int
    var rows: Int
    var cells: [PuzzleCell]
    var words: [PuzzleWord]
}

func loadPuzzles() -> [Puzzle] {
    var out: [Puzzle] = []
    for i in 1...12 {
        let name = String(format: "puzzle-%02d", i)
        if let url = Bundle.main.url(forResource: name, withExtension: "json"),
           let data = try? Data(contentsOf: url),
           let p = try? JSONDecoder().decode(Puzzle.self, from: data) {
            out.append(p)
        }
    }
    return out
}

// MARK: - Game types

enum Difficulty: String, CaseIterable, Identifiable {
    case easy, normal, hard
    var id: String { rawValue }
    var title: String {
        switch self {
        case .easy: return "Easy"
        case .normal: return "Normal"
        case .hard: return "Hard"
        }
    }
    /// Chance the AI places each tile correctly when it can.
    var solveChance: Double {
        switch self {
        case .easy: return 0.45
        case .normal: return 0.55
        case .hard: return 0.85
        }
    }
    /// Chance the AI fumbles a tile onto a wrong square.
    var mistakeChance: Double {
        switch self {
        case .easy: return 0.16
        case .normal: return 0.14
        case .hard: return 0.06
        }
    }
    /// Fraction of the puzzle's words the AI "knows".
    var knownFraction: Double {
        switch self {
        case .easy: return 0.45
        case .normal: return 0.55
        case .hard: return 0.85
        }
    }
}

enum GameMode {
    case solo(Difficulty)
    case passAndPlay
    /// Advanced mode: element names clued by chemical symbols, hard CPU.
    case elements
    /// Relaxed solo: no timer, no opponent. Just solve at your own pace.
    case practice
    /// Quick battle vs CPU: 5-minute game clock, most points wins.
    case blitz(Difficulty)
}

struct Tile: Identifiable {
    let id = UUID()
    var letter: String
    var used: Bool = false
}

/// Weighted English letter distribution (Scrabble-like) for the tile rack.
let letterBag: [String] = {
    let weights: [(String, Int)] = [
        ("E", 12), ("A", 9), ("I", 9), ("O", 8), ("N", 6), ("R", 6),
        ("T", 6), ("L", 4), ("S", 4), ("U", 4), ("D", 4), ("G", 3),
        ("B", 2), ("C", 2), ("M", 2), ("P", 2), ("F", 2), ("H", 2),
        ("V", 2), ("W", 2), ("Y", 2), ("K", 1), ("J", 1), ("X", 1),
        ("Q", 1), ("Z", 1)
    ]
    var bag: [String] = []
    for (letter, count) in weights {
        bag += Array(repeating: letter, count: count)
    }
    return bag
}()

func drawTiles(_ n: Int) -> [Tile] {
    return (0..<n).map { _ in Tile(letter: letterBag.randomElement() ?? "E") }
}

// MARK: - Background music (original, synthesized in code)

/// Original background music for S.W.I.S.H, synthesized in code with
/// AVAudioEngine — no audio files and no third-party music.
/// A cheerful, light puzzle-game loop (soft pads, plucky pentatonic melody,
/// gentle bass) with the same feel as the genre leaders, but our own tune.
final class MusicManager: ObservableObject {
    static let shared = MusicManager()

    /// User toggle, persisted. Defaults to on.
    @Published var enabled: Bool {
        didSet {
            UserDefaults.standard.set(enabled, forKey: "swish.musicEnabled")
            if enabled { start() } else { stop() }
        }
    }

    /// Music volume 0...1, persisted. Defaults to 0.8.
    @Published var volume: Double {
        didSet {
            UserDefaults.standard.set(volume, forKey: "swish.musicVolume")
            player?.volume = Float(volume)
        }
    }

    private var engine: AVAudioEngine?
    private var player: AVAudioPlayerNode?

    private init() {
        if UserDefaults.standard.object(forKey: "swish.musicEnabled") == nil {
            UserDefaults.standard.set(true, forKey: "swish.musicEnabled")
        }
        enabled = UserDefaults.standard.bool(forKey: "swish.musicEnabled")
        let savedVolume = UserDefaults.standard.object(forKey: "swish.musicVolume") as? Double
        volume = min(1.0, max(0.0, savedVolume ?? 0.8))
        NotificationCenter.default.addObserver(
            forName: AVAudioSession.interruptionNotification,
            object: nil, queue: .main
        ) { [weak self] note in self?.handleInterruption(note) }
    }

    /// Starts the music loop. No-op when disabled or already playing.
    func start() {
        guard enabled, engine == nil else { return }
        do {
            try AVAudioSession.sharedInstance().setCategory(.playback, mode: .default, options: [.mixWithOthers])
            try AVAudioSession.sharedInstance().setActive(true)
        } catch { return }
        let engine = AVAudioEngine()
        let player = AVAudioPlayerNode()
        let format = Self.loopFormat
        engine.attach(player)
        engine.connect(player, to: engine.mainMixerNode, format: format)
        engine.prepare()
        do { try engine.start() } catch { return }
        player.scheduleBuffer(Self.makeLoop(), at: nil, options: .loops)
        player.volume = Float(volume)
        player.play()
        self.engine = engine
        self.player = player
    }

    /// Stops the music and releases the engine.
    func stop() {
        player?.stop()
        engine?.stop()
        player = nil
        engine = nil
        try? AVAudioSession.sharedInstance().setActive(false,
                                                      options: .notifyOthersOnDeactivation)
    }

    private func handleInterruption(_ note: Notification) {
        guard let raw = note.userInfo?[AVAudioSessionInterruptionTypeKey] as? UInt,
              let type = AVAudioSession.InterruptionType(rawValue: raw) else { return }
        if type == .began {
            player?.pause()
        } else if type == .ended, enabled {
            player?.play()
        }
    }

    // MARK: - Loop synthesis

    private static let sampleRate = 44_100.0
    /// 4 chords x 2.4 s: C - Am - F - G.
    private static let loopSeconds = 9.6

    private static var loopFormat: AVAudioFormat {
        AVAudioFormat(standardFormatWithSampleRate: sampleRate, channels: 2)!
    }

    private static func makeLoop() -> AVAudioPCMBuffer {
        let frames = AVAudioFrameCount(sampleRate * loopSeconds)
        let buffer = AVAudioPCMBuffer(pcmFormat: loopFormat, frameCapacity: frames)!
        buffer.frameLength = frames
        let l = buffer.floatChannelData![0]
        let r = buffer.floatChannelData![1]

        // (pad root, third, fifth, bass root) in Hz.
        let chords: [(Double, Double, Double, Double)] = [
            (130.81, 164.81, 196.00, 65.41),  // C
            (110.00, 130.81, 164.81, 55.00),  // Am
            ( 87.31, 110.00, 130.81, 43.65),  // F
            ( 98.00, 123.47, 146.83, 49.00),  // G
        ]
        let chordLen = loopSeconds / Double(chords.count)

        // Cheerful pentatonic motif, one note per 0.6 s beat.
        let melody: [Double] = [
            659.25, 783.99, 880.00, 783.99,
            659.25, 587.33, 523.25, 587.33,
            659.25, 783.99, 880.00, 1046.50,
            880.00, 783.99, 659.25, 587.33,
        ]
        let beat = 0.6
        let twoPi = 2.0 * Double.pi

        for i in 0..<Int(frames) {
            let t = Double(i) / sampleRate
            var s = 0.0

            // Pad: soft chord bed with gentle in/out ramps.
            let ci = min(chords.count - 1, Int(t / chordLen))
            let ct = t - Double(ci) * chordLen
            let padEnv = smooth(a: 0, b: 0.5, x: ct) * smooth(a: chordLen, b: chordLen - 0.5, x: ct)
            let (pr, pt, pf, _) = chords[ci]
            s += 0.033 * padEnv * (sin(twoPi * pr * t) + sin(twoPi * pt * t) + sin(twoPi * pf * t))

            // Bass: soft pluck on each chord change.
            let bass = chords[ci].3
            s += 0.16 * exp(-ct * 4.0) * sin(twoPi * bass * t)

            // Melody: bright plucks with a touch of harmonic.
            let mi = Int(t / beat)
            if mi < melody.count {
                let nt = t - Double(mi) * beat
                if nt < 0.58 {
                    let f = melody[mi]
                    let env = exp(-nt * 7.0)
                    s += 0.14 * env * (sin(twoPi * f * nt) + 0.35 * sin(2 * twoPi * f * nt))
                }
            }

            let v = Float(s * 0.9)
            l[i] = v
            r[i] = v
        }
        return buffer
    }

    /// Smooth 0->1 ramp from a to b (works with a > b for ramp-down).
    private static func smooth(a: Double, b: Double, x: Double) -> Double {
        let t = min(1.0, max(0.0, (x - a) / (b - a)))
        return t * t * (3.0 - 2.0 * t)
    }
}

// MARK: - Daily play reminder (local notification)

/// On-device "come back and play" nudge. No server needed: when the app goes
/// to the background we schedule one local notification for 24 hours after
/// the last finished game. Opening the app or finishing a game clears it, so
/// it only ever fires after a full day away.
final class PlayReminder: ObservableObject {
    static let shared = PlayReminder()

    /// User toggle, persisted. Defaults to on.
    @Published var enabled: Bool {
        didSet {
            UserDefaults.standard.set(enabled, forKey: "swish.reminderEnabled")
            if enabled { schedule() } else { cancel() }
        }
    }

    private let requestID = "swish-daily-reminder"
    private let askedKey = "swish.reminderAsked"
    private let lastPlayKey = "swish.reminderLastPlay"

    private init() {
        if UserDefaults.standard.object(forKey: "swish.reminderEnabled") == nil {
            UserDefaults.standard.set(true, forKey: "swish.reminderEnabled")
        }
        enabled = UserDefaults.standard.bool(forKey: "swish.reminderEnabled")
    }

    /// Ask the system for notification permission once, on first launch.
    func requestPermissionIfNeeded() {
        let d = UserDefaults.standard
        guard !d.bool(forKey: askedKey) else { return }
        d.set(true, forKey: askedKey)
        UNUserNotificationCenter.current()
            .requestAuthorization(options: [.alert, .sound]) { _, _ in }
    }

    /// Call when a game finishes: stamps "last played" and clears any pending nudge.
    func recordPlay() {
        UserDefaults.standard.set(Date(), forKey: lastPlayKey)
        cancel()
    }

    /// Call when the app backgrounds: schedules one nudge 24h after last play.
    func schedule() {
        guard enabled else { return }
        let center = UNUserNotificationCenter.current()
        center.getNotificationSettings { [weak self] settings in
            guard let self = self, settings.authorizationStatus == .authorized else { return }
            let last = UserDefaults.standard.object(forKey: self.lastPlayKey) as? Date ?? Date()
            let interval = max(last.addingTimeInterval(24 * 3600).timeIntervalSinceNow, 60)
            let content = UNMutableNotificationContent()
            content.title = "S.W.I.S.H - Crossword Battle ARCADE"
            content.body = "A fresh crossword battle is waiting for you."
            content.sound = .default
            let trigger = UNTimeIntervalNotificationTrigger(timeInterval: interval, repeats: false)
            center.add(UNNotificationRequest(identifier: self.requestID, content: content, trigger: trigger))
        }
    }

    /// Call when the app comes forward: they're back, no nudge needed.
    func cancel() {
        UNUserNotificationCenter.current().removePendingNotificationRequests(withIdentifiers: [requestID])
    }
}
